def decode_wire(data: Any) -> WireEnvelope:
    """Decode a codingagent.v1 payload under closed-world rules.

    Every object rejects a key outside its frozen set at every nesting depth, a
    duplicate key is an error rather than last-wins, and no error message ever
    quotes a rejected value.
    """
    if isinstance(data, (str, bytes, bytearray)):
        data = loads_strict(data)
    return _decode_envelope(data, "")


def canonical_json(envelope: WireEnvelope) -> bytes:
    """Render the frozen canonical form.

    UTF-8, keys sorted lexicographically at every level, no insignificant
    whitespace, no non-ASCII escaping and no trailing newline. Go is configured
    identically in wire_gen.go; neither language's default matches the other's.
    """
    return json.dumps(
        envelope.to_canonical(),
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
    ).encode("utf-8")


def allowed_keys() -> List[str]:
    """Every admitted field name as a dotted path, sorted.

    Derived from the generated key sets so a test cannot drift from the decoder
    it is checking.
    """
    out: List[str] = []
    for prefix, keys in (
        ("", KEYS_ENVELOPE),
        ("process", KEYS_PROCESS_INFO),
        ("kanban", KEYS_KANBAN_INFO),
        ("metrics", KEYS_METRICS_INFO),
        ("metrics.tool_counts", KEYS_TOOL_COUNTS),
        ("network", KEYS_NETWORK_INFO),
    ):
        out.extend(_join(prefix, k) for k in keys)
    return sorted(out)
